<?php require dirname(__DIR__).'/app/bootstrap.php';require ROOT.'/app/helpers.php';
$r=new App\Router;$p=new App\Controllers\PublicController;
$r->get('/',[$p,'home']);$r->get('/berita',[$p,'index']);$r->get('/berita/{slug}',[$p,'show']);$r->get('/kategori/{slug}',[$p,'category']);$r->get('/tag/{slug}',[$p,'tag']);$r->get('/cari',[$p,'search']);$r->get('/tentang',fn()=>$p->page('tentang','Tentang'));$r->get('/kontak',fn()=>$p->page('kontak','Kontak'));$r->get('/kebijakan-privasi',fn()=>$p->page('kebijakan-privasi','Kebijakan Privasi'));$r->get('/sitemap.xml',[$p,'sitemap']);
$auth=new App\Controllers\AuthController;$r->get('/admin/login',[$auth,'form']);$r->post('/admin/login',[$auth,'login']);$r->post('/admin/logout',[$auth,'logout']);
if(user()){$a=new App\Controllers\AdminController;$r->get('/admin',[$a,'dashboard']);$r->get('/admin/artikel',[$a,'posts']);$r->get('/admin/artikel/baru',[$a,'form']);$r->post('/admin/artikel/baru',[$a,'save']);$r->get('/admin/artikel/{id}/edit',[$a,'form']);$r->post('/admin/artikel/{id}/edit',[$a,'save']);$r->get('/admin/artikel/{id}/preview',[$a,'preview']);foreach(['kategori','tag'] as $type){$r->get('/admin/'.$type,fn()=>$a->taxonomy($type));$r->post('/admin/'.$type,fn()=>$a->taxonomy($type));}$r->get('/admin/pengaturan',[$a,'settings']);$r->post('/admin/pengaturan',[$a,'settings']);$r->get('/admin/media',[$a,'media']);$r->post('/admin/media',[$a,'media']);$r->get('/admin/pengguna',[$a,'users']);$r->post('/admin/pengguna',[$a,'users']);$r->get('/admin/halaman',[$a,'pages']);$r->post('/admin/halaman',[$a,'pages']);}
$r->dispatch($_SERVER['REQUEST_METHOD'],$_SERVER['REQUEST_URI']);
